output_text:
[
  {
    "id": "return_cart_to_nw_bay",
    "text": "Anyone who takes a cart is obliged to return it to the north-west cart return before leaving the store.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return": "at(0,1)",
        "agent_has_cart": "hasCart",
        "cart_parked_nw": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_nw": {
          "pre": {
            "and": [
              "hasCart",
              "at(0,1)",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_nw"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Customers are prohibited from exiting the supermarket while still pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "agent_has_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "agent_has_cart"
        ]
      }
    }
  },
  {
    "id": "leave_cart_only_at_return_points",
    "text": "A cart may only be put down at an approved cart return location, not abandoned elsewhere in the store.",
    "abstraction": {
      "state_properties": {
        "approved_cart_return": {
          "or": [
            "at(0,1)",
            "at(1,5)"
          ]
        },
        "unapproved_cart_location": {
          "not": "approved_cart_return"
        }
      },
      "events": {
        "leave_cart_unapproved": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "unapproved_cart_location"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_unapproved"
    }
  },
  {
    "id": "purchased_items_must_ride_in_cart",
    "text": "Customers are prohibited from picking up shelf items unless they currently have a cart available for carrying them.",
    "abstraction": {
      "state_properties": {
        "agent_has_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Customers must not carry merchandise by hand; items should be transported using a cart instead.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "become_hand_full"
        ]
      }
    }
  },
  {
    "id": "shopping_cart_must_be_returned_after_item_pickup",
    "text": "After putting any item into a cart, the customer is obliged to park that cart at the north-west return station before exiting.",
    "abstraction": {
      "state_properties": {
        "agent_has_cart": "hasCart",
        "nw_cart_return": "at(0,1)",
        "cart_parked_nw": "cartAt(0,1)"
      },
      "events": {
        "item_loaded_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": "hasCart"
        },
        "park_cart_nw": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "hasCart",
              "at(0,1)"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded_into_cart",
      "discharge": "park_cart_nw"
    }
  },
  {
    "id": "no_carts_in_exit_corridor",
    "text": "Shopping carts are prohibited in the long southern exit corridor, so customers must leave carts behind before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "southern_exit_corridor": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "agent_has_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "southern_exit_corridor",
          "agent_has_cart"
        ]
      }
    }
  },
  {
    "id": "middle_station_purchase_requires_cart_return",
    "text": "Interacting with the middle station while shopping creates an obligation to perform an explicit cart-return action at the north-west desk before departure.",
    "abstraction": {
      "state_properties": {
        "middle_station": "at(2,2)",
        "nw_desk_cart_return": "at(0,1)",
        "agent_has_cart": "hasCart"
      },
      "events": {
        "middle_station_item_pickup": {
          "pre": {
            "and": [
              "at(2,2)",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "explicit_nw_cart_return": {
          "pre": {
            "and": [
              "at(0,1)",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "middle_station_item_pickup",
      "discharge": "explicit_nw_cart_return"
    }
  }
]
